#!/usr/bin/env python3
"""Run a command under a pty, feeding scripted input. Prints all pty output."""
import os, sys, pty, select, termios, tty, time, signal, errno

def main():
    # argv: pty_run.py "input1\ninput2\n" cmd args...
    feed = sys.argv[1].encode().decode('unicode_escape').encode()
    cmd = sys.argv[2:]
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
        os._exit(1)
    out = b''
    if feed:
        time.sleep(0.3)
        os.write(fd, feed)
    deadline = time.time() + 25
    while time.time() < deadline:
        try:
            r, _, _ = select.select([fd], [], [], 0.4)
        except OSError:
            break
        if fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d:
                break
            out += d
        else:
            p, st = os.waitpid(pid, os.WNOHANG)
            if p == pid:
                # drain
                while True:
                    try:
                        r, _, _ = select.select([fd], [], [], 0.2)
                        if fd not in r: break
                        d = os.read(fd, 65536)
                        if not d: break
                        out += d
                    except OSError:
                        break
                break
    try:
        p, st = os.waitpid(pid, 0)
        rc = os.waitstatus_to_exitcode(st)
    except Exception:
        rc = -1
    sys.stdout.buffer.write(out)
    sys.stdout.flush()
    sys.stderr.write("\n[exit %s]\n" % rc)

main()

