#!/usr/bin/env python3
"""Collect autogenerated passphrases by running age -p and killing it early."""
import os, sys, pty, select, time, signal, re

N = int(sys.argv[1])
words = set()
pat = re.compile(rb'passphrase "([a-z\-]+)"')
for it in range(N):
    pid, fd = pty.fork()
    if pid == 0:
        os.close(2)
        os.open('/dev/null', os.O_WRONLY)
        os.execv('/workspace/executable', ['age', '-p', '-o', '/tmp/w/.junk', '/tmp/w/pt.txt'])
        os._exit(1)
    out = b''
    fed = False
    deadline = time.time() + 3.0
    while time.time() < deadline:
        r, _, _ = select.select([fd], [], [], 0.05)
        if fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out += d
        if not fed:
            os.write(fd, b'\n')
            fed = True
        if b'passphrase "' in out and out.rstrip().endswith(b'"\r'):
            break
        m = pat.search(out)
        if m: break
    try:
        os.kill(pid, signal.SIGKILL)
    except OSError:
        pass
    try: os.close(fd)
    except OSError: pass
    try: os.waitpid(pid, 0)
    except Exception: pass
    m = pat.search(out)
    if m:
        for w in m.group(1).split(b'-'):
            words.add(w.decode())
    else:
        sys.stderr.write('MISS: %r\n' % out[-120:])
print('\n'.join(sorted(words)))
sys.stderr.write('total words: %d\n' % len(words))

